package com.tastenest.servlet;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import com.tastenest.util.DB;
@WebServlet("/feedback") public class FeedbackServlet extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{res.setContentType("application/json");try{DB.init();Object u=req.getSession().getAttribute("userId");if(u==null){res.setStatus(401);res.getWriter().print("{\"ok\":false,\"error\":\"Please login first\"}");return;}try(Connection c=DB.get();PreparedStatement p=c.prepareStatement("INSERT INTO feedback(order_id,user_id,rating,comment) VALUES(?,?,?,?)")){p.setInt(1,Integer.parseInt(req.getParameter("orderId")));p.setInt(2,(Integer)u);p.setInt(3,Integer.parseInt(req.getParameter("rating")));p.setString(4,req.getParameter("comment"));p.executeUpdate();}res.getWriter().print("{\"ok\":true}");}catch(Exception e){res.setStatus(500);res.getWriter().print("{\"ok\":false,\"error\":\"Could not save feedback\"}");}}}
